[
  {
    "text": "The WorldLines paper explicitly describes all benchmark tasks as combining partial observability or state overwrite with the need to use long-term memory, without any task variant that strips these complications.",
    "topic": "task design coupling"
  },
  {
    "text": "The paper's stated goal about translating long-term memory into embodied plans is framed as a means to overcome partial observability and overwritten states, not as an isolated capability to be assessed separately.",
    "topic": "articulation of aim"
  },
  {
    "text": "No separate evaluation metric or scoring rubric in the WorldLines benchmark isolates the translation of long-term memory from the success in handling partial observability or state overwrites.",
    "topic": "evaluation isolation"
  },
  {
    "text": "The benchmark's challenge of translating long-term memory into plans is inherently dependent on the presence of partial observability or memory overwriting to motivate the need for long-term memory, making isolation unnatural for the intended setting.",
    "topic": "dependency rationale"
  }
]
